+/** The language to answer in for an Accept-Language header, or `fallback` if none is supported. */
+export function pickLanguage(header, fallback = LANGUAGES[0]) {
+  let best = null;
+  let bestQ = 0;
+  for (const part of String(header ?? "").split(",")) {
+    const [range, ...attrs] = part.trim().split(";");
+    const tag = range.trim().toLowerCase();
+    if (!tag) continue;
+    let q = 1;
+    for (const attr of attrs) {
+      const [k, v] = attr.split("=").map((x) => x.trim());
+      if (k.toLowerCase() === "q") q = /^(0(\.\d{0,3})?|1(\.0{0,3})?)$/.test(v ?? "") ? Number(v) : 0;
+    }
+    const primary = tag.split("-")[0];
+    const lang = primary === "*" ? fallback : LANGUAGES.includes(primary) ? primary : null;
+    if (lang && q > bestQ) {
+      best = lang;
+      bestQ = q;
+    }
+  }
+  return best ?? fallback;
+}
